contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 value) public {
        // give this contract some supply by minting (owner is this contract)
        c.mintToken(address(this), 1000);
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        bool ok;
        if (value <= balBefore) {
            ok = c.transfer(address(this), value);
            assert(ok && c.balanceOf(address(this)) == balBefore && c.totalSupply() == supplyBefore);
        } else {
            bool reverted;
            try c.transfer(address(this), value) returns (bool s) { reverted = false; ok = s; }
            catch { reverted = true; }
            assert(reverted && c.balanceOf(address(this)) == balBefore && c.totalSupply() == supplyBefore);
        }
    }

    receive() external payable {}
}

