contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 supply, address target, uint256 mintAmount) public {
        require(target != address(0));
        // Setup: give this contract (msg.sender to c) the whole supply via deployment.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        bool reverted;
        try c.mintToken(target, mintAmount) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && c.balanceOf(target) == 0 && c.totalSupply() == supplyBefore && c.balanceOf(address(this)) == balBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 tAmount, uint256 burnAmount) public {
        require(target != address(0));
        require(!c.frozenAccount(target));
        uint256 supplyBefore = c.totalSupply();
        uint256 myBal = c.balanceOf(address(this));
        require(tAmount <= myBal);
        require(burnAmount <= myBal - tAmount);
        c.transfer(target, tAmount);
        c.burn(burnAmount);
        assert(
            c.totalSupply() == supplyBefore - burnAmount &&
            c.balanceOf(address(this)) + c.balanceOf(target) == c.totalSupply()
        );
    }
    receive() external payable {}
}
